SourceCode.Declaration:
/// <summary>
/// Runnable job: correct an existing purchase product receipt on the warehouse
/// virtual location InventLocation.EOLWMSLocationIdDefaultVirtualReceipt.
/// Fill the constants in <c>main</c>, compile, then Open / Run in the purchase
/// order company. If started from a VendPackingSlipJour record, that journal is used.
/// </summary>
public class EOLPurchPackingSlipCorrectorJob
{
}

Method.Source:
/// <summary>
/// Entry point.
/// </summary>
/// <param name="_args">
/// Optional. When the caller record is <c>VendPackingSlipJour</c>, its ids are used.
/// </param>
public static void main(Args _args)
{
    PackingSlipId       packingSlipId;
    PurchId             purchId;
    InventTransId       inventTransId;
    WMSLocationId       wmsLocationId;
    Qty                 newReceiveQty;
    VendPackingSlipJour packingSlipJour;

    // ===== Fill these values before running =====
    packingSlipId   = 'PR-000123';
    purchId         = 'PO-000456';
    inventTransId   = '';
    wmsLocationId   = '';
    newReceiveQty   = 7;
    // ============================================

    if (_args && _args.record() && _args.record().TableId == tableNum(VendPackingSlipJour))
    {
        packingSlipJour = _args.record();
        packingSlipId = packingSlipJour.PackingSlipId;
        purchId = packingSlipJour.PurchId;
    }

    if (!packingSlipId)
    {
        throw error("@EOLPackingSlip:PackingSlipNotFound");
    }

    info(strFmt("@EOLPackingSlip:PurchJobStarting",
        packingSlipId,
        purchId,
        newReceiveQty));

    EOLPurchPackingSlipCorrector::correctQty(
        packingSlipId,
        newReceiveQty,
        purchId,
        inventTransId,
        wmsLocationId);
}
